42	// accumulator grid, fp16 operands with fp32 accumulators, §2.3's padded
43	// leading dimension on the A operand, and B in the §2.8 fragment tiling
44	// (tile (nt, kt) is 256 contiguous halves holding element (k, n) at
45	// (n%16)*16 + k%16, kt fastest). It is a separate shader rather than another
46	// -D arm of dit_gemm.comp because both epilogues read a *second* activation
47	// tensor and one of them writes a narrower C than the GEMM computes — which
48	// is not an epilogue that file has a slot for, and it is the whole point of
49	// this one.
50	//
51	// No bounds checks, as everywhere else in this ladder: the host pads M up to
52	// BM and the arenas are zeroed once, so the pad rows carry the products of
53	// zeros and their outputs are ignored.
54	
55	#include "llm_common.glsl"
56	
57	#ifndef MODE
58	#define MODE 0
59	#endif
60	#ifndef WM
61	#define WM 4        // accumulator tiles, M direction
62	#endif
63	#ifndef WN
64	#define WN 4        // accumulator tiles, N direction; MODE 1 needs a multiple of 4
65	#endif
66	#ifndef BK_TILES
67	#define BK_TILES 2  // K-slab depth, in 16-wide cooperative-matrix steps
68	#endif
69	// The stream count is compiled in rather than read from pc.hc: MODE 1's
70	// collapse is a reduction over it *and* the weight permutation that puts the
71	// streams of one feature in one workgroup is cut on it, so a mismatch would
72	// be a wrong answer and not a slow one. The host checks the checkpoint says 4.
73	#ifndef HC_STREAMS
74	#define HC_STREAMS 4
75	#endif
76	
77	#define TILE 16
78	#define BM (WM * TILE)
79	#define BN (WN * TILE)
80	#define BK (BK_TILES * TILE)
81	#define WAVE 64
82	
83	layout(local_size_x = WAVE) in;
84	
85	#define FRAG_A_T coopmat<float16_t, gl_ScopeSubgroup, TILE, TILE, gl_MatrixUseA>
86	#define FRAG_B_T coopmat<float16_t, gl_ScopeSubgroup, TILE, TILE, gl_MatrixUseB>
87	#define ACC_T coopmat<float, gl_ScopeSubgroup, TILE, TILE, gl_MatrixUseAccumulator>
88	#define ACC16_T coopmat<float16_t, gl_ScopeSubgroup, TILE, TILE, gl_MatrixUseAccumulator>
89	
90	#if MODE == 0
91	#define A_BUF_OFF pc.xnOff
92	#define A_LDA pc.lda
93	#else
94	#define A_BUF_OFF pc.loOff
95	#define A_LDA pc.ldaLo
96	// The gate tiles go through LDS on the way to the collapse. Storing the
97	// accumulator and reading it back with ordinary indexing is what lets the
98	// collapse pair a gate element with its xn element without depending on how
99	// the implementation maps matrix elements to lanes -- which the cooperative
100	// matrix extension does not define. It is 16 KB and one barrier.
101	shared float gateLDS[BM * BN];
102	#endif
103	
104	float sigmoidf(float x) { return 1.0 / (1.0 + exp(-x)); }
105	
106	void main() {
107	    uint wn0 = gl_WorkGroupID.x * BN;
108	    uint wm0 = gl_WorkGroupID.y * BM;
109	
110	    ACC_T acc[WM][WN];
111	    [[unroll]] for (uint i = 0u; i < WM; i++) {
112	        [[unroll]] for (uint j = 0u; j < WN; j++) {
113	            acc[i][j] = ACC_T(0.0);
114	        }
115	    }
116	
117	    uint ktiles = pc.gemmK / TILE;
118	    for (uint k0 = 0u; k0 < pc.gemmK; k0 += BK) {
119	        [[unroll]] for (uint kt = 0u; kt < BK_TILES; kt++) {
120	            FRAG_A_T fragA[WM];
121	            FRAG_B_T fragB[WN];
122	            [[unroll]] for (uint i = 0u; i < WM; i++) {
123	                coopMatLoad(fragA[i], hact, A_BUF_OFF + (wm0 + i * TILE) * A_LDA + k0 + kt * TILE,
124	                    A_LDA, gl_CooperativeMatrixLayoutRowMajor);
125	            }
126	            [[unroll]] for (uint j = 0u; j < WN; j++) {
127	                coopMatLoad(fragB[j], w16, pc.bOff +
128	                    (((wn0 + j * TILE) / TILE) * ktiles + (k0 + kt * TILE) / TILE) * (TILE * TILE),
129	                    TILE, gl_CooperativeMatrixLayoutColumnMajor);
130	            }
131	            [[unroll]] for (uint i = 0u; i < WM; i++) {
132	                [[unroll]] for (uint j = 0u; j < WN; j++) {
133	                    acc[i][j] = coopMatMulAdd(fragA[i], fragB[j], acc[i][j]);
134	                }
135	            }
136	        }
137	    }
138	
139	#if MODE == 0
140	    // Down and inject in one store pass. The gate's branch gets silu(x/hc)
141	    // applied on the accumulator and is narrowed into the fp16 arena as the
142	    // next matmul's A operand; inject's single tile is written fp32, because
143	    // it is read by the combine as a scalar per stream and never by a
144	    // fragment load.
145	    float invHC = 1.0 / float(pc.hc);
146	    uint injStride = pc.gemmN - pc.lowRank;
147	    [[unroll]] for (uint i = 0u; i < WM; i++) {
148	        [[unroll]] for (uint j = 0u; j < WN; j++) {
149	            uint n0 = wn0 + j * TILE;
150	            uint m0 = wm0 + i * TILE;
151	            if (n0 < pc.lowRank) {
152	                ACC16_T out;
153	                [[unroll]] for (uint e = 0u; e < acc[i][j].length(); e++) {
154	                    float v = float(acc[i][j][e]) * invHC;
155	                    out[e] = float16_t(v * sigmoidf(v));
156	                }
157	                coopMatStore(out, hact, pc.loOff + m0 * pc.ldaLo + n0, pc.ldaLo,
158	                    gl_CooperativeMatrixLayoutRowMajor);
159	            } else {
160	                coopMatStore(acc[i][j], act, pc.injOff + m0 * injStride + (n0 - pc.lowRank),
161	                    injStride, gl_CooperativeMatrixLayoutRowMajor);
162	            }
163	        }
164	    }
165	#else
166	    // The gate, then the collapse, with the 10240-wide tensor never leaving
167	    // the workgroup.
168	    [[unroll]] for (uint i = 0u; i < WM; i++) {
169	        [[unroll]] for (uint j = 0u; j < WN; j++) {
170	            ACC_T g;
171	            [[unroll]] for (uint e = 0u; e < acc[i][j].length(); e++) {
172	                g[e] = sigmoidf(float(acc[i][j][e]));
173	            }

