			{"hc_gate", g.Gate(), tolLlamaG},
			{"hc_mixed", g.Mixed(), tolLlamaM},
			{"hc_inject", g.Inject(), tolInject},
		} {
			want, err := tr.Get(fmt.Sprintf("%s-%d", tc.name, ref.layer), ref.nth)
			if err != nil {
				t.Fatal(err)
			}
			r, err := compare(tc.got, want.Vals)
			if err != nil {
				t.Fatalf("blk.%d.hc_%s %s: %v", ref.layer, ref.side, tc.name, err)
			}
			t.Logf("blk.%d.hc_%-4s %-10s %v", ref.layer, ref.side, tc.name, r)
			if r.rms > tc.tol {
				t.Errorf("blk.%d.hc_%s %s: rms %.3e over %.1e (%v)",
