	kv.GemmM, kv.GemmK = uint32(roundUpInt(g.rows, pleKVBM)), uint32(c.NEmbd)
	add("kv", "kv", uint32(g.kvN()/pleKVBN), uint32(roundUpInt(g.rows, pleKVBM)/pleKVBM), kv)

	add("gate", "gate", uint32(g.rows), uint32(c.HC), base)
	add("conv", "conv", uint32(g.rows), uint32((wide+255)/256), base)
