36	// reduce2 sums two per-thread values across the workgroup and leaves both in
37	// partA[0] and partB[0].
38	void reduce2(uint tid, float a, float b) {
39	    partA[tid] = a;
40	    partB[tid] = b;
41	    barrier();
42	    for (uint stride = gl_WorkGroupSize.x / 2u; stride > 0u; stride >>= 1u) {
43	        if (tid < stride) {
44	            partA[tid] += partA[tid + stride];
45	            partB[tid] += partB[tid + stride];
46	        }
47	        barrier();
48	    }
49	}
