65	    uint valOff = pc.kvOff + t * pc.gemmN + wide;
66	    uint resOff = pc.resOff + t * wide + ch * n;
67	    uint gk = pc.gammaOff + ch * n;
68	    uint gq = pc.gammaQOff + ch * n;
69	    uint gc = pc.gammaCOff + ch * n;
70	
71	    float sk = 0.0, sq = 0.0;
72	    for (uint i = tid; i < n; i += gl_WorkGroupSize.x) {
73	        float k = act[keyOff + i];
74	        float q = act[resOff + i];
